import{_ as t,a0 as o,w as r,s as d,ao as l,I as i,a1 as e,A as p,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"使用 PySimpleGUI 輕鬆為程序和腳本增加 GUI | LCTT x X-CMD","titleTemplate":false,"description":"使用 PySimpleGUI 輕鬆為程序和腳本增加 GUI | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 PySimpleGUI 輕鬆為程序和腳本增加 GUI | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 PySimpleGUI 輕鬆為程序和腳本增加 GUI | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180829 Add GUIs to your programs and scripts easily with PySimpleGUI","title":"使用 PySimpleGUI 輕鬆為程序和腳本增加 GUI","tag":"201809","desc":""},"relativePath":"201809/20180829 Add GUIs to your programs and scripts easily with PySimpleGUI.md","filePath":"[post].md"}'),u={name:"201809/20180829 Add GUIs to your programs and scripts easily with PySimpleGUI.md"};function h(g,s,c,b,m,k){const n=o("Link");return r(),d("div",null,[s[26]||(s[26]=l('<h1 id="使用-pysimplegui-輕鬆為程序和腳本增加-gui" tabindex="-1">使用 PySimpleGUI 輕鬆為程序和腳本增加 GUI <a class="header-anchor" href="#使用-pysimplegui-輕鬆為程序和腳本增加-gui" aria-label="Permalink to “使用 PySimpleGUI 輕鬆為程序和腳本增加 GUI”">​</a></h1><blockquote><p>五分鐘創建定製 GUI。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/web_browser_desktop_devlopment_design_system_computer.jpg?itok=pfqRrJgh" alt=""></p><p>對於 <code>.exe</code> 類型的程序文件，我們可以通過雙擊鼠標左鍵打開；但對於 <code>.py</code> 類型的 Python 程序，幾乎不會有人嘗試同樣的操作。對於一個（非程序員類型的）典型用户，他們雙擊打開 <code>.exe</code> 文件時預期彈出一個可以交互的窗體。基於 Tkinter，可以通過<ruby>標準 Python 安裝<rt>standard Python installations</rt></ruby>的方式提供 GUI，但很多程序都不太可能這樣做。</p><p>如果打開 Python 程序並進入 GUI 界面變得如此容易，以至於真正的初學者也可以掌握，會怎樣呢？會有人感興趣並使用嗎？這個問題不好回答，因為直到今天創建自定義 GUI 佈局仍不是件容易的事情。</p><p>在為程序或腳本增加 GUI 這件事上，似乎存在能力的“錯配”。（缺乏這方面能力的）真正的初學者被迫只能使用命令列方式，而很多（具備這方面能力的）高級程序員卻不願意花時間創建一個 Tkinter GUI。</p><h3 id="gui-框架" tabindex="-1">GUI 框架 <a class="header-anchor" href="#gui-框架" aria-label="Permalink to “GUI 框架”">​</a></h3><p>Python 的 GUI 框架並不少，其中 Tkinter，wxPython，Qt 和 Kivy 是幾種比較主流的框架。此外，還有不少在上述框架基礎上封裝的簡化框架，例如 EasyGUI，PyGUI 和 Pyforms 等。</p><p>但問題在於，對於初學者（這裏是指編程經驗不超過 6 個月的用户）而言，即使是最簡單的主流框架，他們也無從下手；他們也可以選擇封裝過的（簡化）框架，但仍難以甚至無法創建自定義 GUI <ruby>佈局<rt>layout</rt></ruby>。即便學會了某種（簡化）框架，也需要編寫連篇累牘的代碼。</p>',9)),i("p",null,[e(n,{href:"https://github.com/MikeTheWatchGuy/PySimpleGUI"},{default:p(()=>[...s[0]||(s[0]=[a("PySimpleGUI",-1)])]),_:1}),s[1]||(s[1]=a(" 嘗試解決上述 GUI 難題，它提供了一種簡單明瞭、易於理解、方便自定義的 GUI 接口。如果使用 PySimpleGUI，很多複雜的 GUI 也僅需不到 20 行代碼。",-1))]),s[27]||(s[27]=l('<h3 id="秘訣" tabindex="-1">秘訣 <a class="header-anchor" href="#秘訣" aria-label="Permalink to “秘訣”">​</a></h3><p>PySimpleGUI 極為適合初學者的秘訣在於，它已經包含了絕大多數原本需要用户編寫的代碼。PySimpleGUI 會處理按鈕<ruby>回調<rt>callback</rt></ruby>，無需用户編寫代碼。對於初學者，在幾周內掌握函數的概念已經不容易了，要求其理解回調函數似乎有些強人所難。</p><p>在大部分 GUI 框架中，佈局 GUI <ruby>小部件<rt>widgets</rt></ruby>通常需要寫一些代碼，每個小部件至少 1-2 行。PySimpleGUI 使用了 “auto-packer” 技術，可以自動創建佈局。因而，佈局 GUI 窗口不再需要 pack 或 grid 系統。</p><p>（LCTT 譯註：這裏提到的 pack 和 grid 都是 Tkinter 的佈局管理器，另外一種叫做 place 。）</p><p>最後，PySimpleGUI 框架編寫中有效地利用了 Python 語言特性，降低用户代碼量並簡化 GUI 數據返回的方式。在<ruby>窗體<rt>form</rt></ruby>佈局中創建小部件時，小部件會被部署到對應的佈局中，無需額外的代碼。</p><h3 id="gui-是什麼" tabindex="-1">GUI 是什麼？ <a class="header-anchor" href="#gui-是什麼" aria-label="Permalink to “GUI 是什麼？”">​</a></h3><p>絕大多數 GUI 只完成一件事情：收集用户數據並返回。在程序員看來，可以歸納為如下的函數調用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>button, values = GUI_Display(gui_layout)</span></span></code></pre></div><p>絕大多數 GUI 支持的用户行為包括鼠標點擊（例如，“確認”，“取消”，“保存”，“是”和“否”等）和內容輸入。GUI 本質上可以歸結為一行代碼。</p><p>這也正是 PySimpleGUI （的簡單 GUI 模式）的工作原理。當執行命令顯示 GUI 後，除非點擊鼠標關閉窗體，否則不會執行任何代碼。</p><p>當然還有更復雜的 GUI，其中鼠標點擊後窗口並不關閉；例如，機器人的遠程控制界面，聊天窗口等。這類複雜的窗體也可以用 PySimpleGUI 創建。</p><h3 id="快速創建-gui" tabindex="-1">快速創建 GUI <a class="header-anchor" href="#快速創建-gui" aria-label="Permalink to “快速創建 GUI”">​</a></h3>',12)),i("p",null,[s[3]||(s[3]=a("PySimpleGUI 什麼時候有用呢？顯然，是你需要 GUI 的時候。僅需不超過 5 分鐘，就可以讓你創建並嘗試 GUI。最便捷的 GUI 創建方式就是從 ",-1)),e(n,{href:"https://pysimplegui.readthedocs.io/en/latest/cookbook/"},{default:p(()=>[...s[2]||(s[2]=[a("PySimpleGUI 經典實例",-1)])]),_:1}),s[4]||(s[4]=a("中拷貝一份代碼。具體操作流程如下：",-1))]),s[28]||(s[28]=l(`<ul><li>找到一個與你需求最接近的 GUI</li><li>從經典實例中拷貝代碼</li><li>粘貼到 IDE 中並運行</li></ul><p>下面我們看一下書中的第一個<ruby>經典實例<rt>recipe</rt></ruby>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import PySimpleGUI as sg</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Very basic form.  Return values as a list</span></span>
<span class="line"><span>form = sg.FlexForm(&#39;Simple data entry form&#39;)  # begin with a blank form</span></span>
<span class="line"><span></span></span>
<span class="line"><span>layout = [</span></span>
<span class="line"><span>          [sg.Text(&#39;Please enter your Name, Address, Phone&#39;)],</span></span>
<span class="line"><span>          [sg.Text(&#39;Name&#39;, size=(15, 1)), sg.InputText(&#39;name&#39;)],</span></span>
<span class="line"><span>          [sg.Text(&#39;Address&#39;, size=(15, 1)), sg.InputText(&#39;address&#39;)],</span></span>
<span class="line"><span>          [sg.Text(&#39;Phone&#39;, size=(15, 1)), sg.InputText(&#39;phone&#39;)],</span></span>
<span class="line"><span>          [sg.Submit(), sg.Cancel()]</span></span>
<span class="line"><span>         ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>button, values = form.LayoutAndRead(layout)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(button, values[0], values[1], values[2])</span></span></code></pre></div><p>運行後會打開一個大小適中的窗體。</p><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui_cookbook-form.jpg" alt=""></p><p>如果你只是想收集一些字符串類型的值，拷貝上述經典實例中的代碼，稍作修改即可滿足你的需求。</p><p>你甚至可以只用 5 行代碼創建一個自定義 GUI 佈局。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import PySimpleGUI as sg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>form = sg.FlexForm(&#39;My first GUI&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>layout = [ [sg.Text(&#39;Enter your name&#39;), sg.InputText()],</span></span>
<span class="line"><span>           [sg.OK()] ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>button, (name,) = form.LayoutAndRead(layout)</span></span></code></pre></div><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui-5-line-form.jpg" alt=""></p><h3 id="_5-分鐘內創建一個自定義-gui" tabindex="-1">5 分鐘內創建一個自定義 GUI <a class="header-anchor" href="#_5-分鐘內創建一個自定義-gui" aria-label="Permalink to “5 分鐘內創建一個自定義 GUI”">​</a></h3><p>在簡單佈局的基礎上，通過修改經典實例中的代碼，5 分鐘內即可使用 PySimpleGUI 創建自定義佈局。</p><p>在 PySimpleGUI 中，<ruby>小部件<rt>widgets</rt></ruby>被稱為<ruby>元素<rt>elements</rt></ruby>。元素的名稱與編碼中使用的名稱保持一致。</p><p>（LCTT 譯註：Tkinter 中使用小部件這個詞）</p><h4 id="核心元素" tabindex="-1">核心元素 <a class="header-anchor" href="#核心元素" aria-label="Permalink to “核心元素”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Text</span></span>
<span class="line"><span>InputText</span></span>
<span class="line"><span>Multiline</span></span>
<span class="line"><span>InputCombo</span></span>
<span class="line"><span>Listbox</span></span>
<span class="line"><span>Radio</span></span>
<span class="line"><span>Checkbox</span></span>
<span class="line"><span>Spin</span></span>
<span class="line"><span>Output</span></span>
<span class="line"><span>SimpleButton</span></span>
<span class="line"><span>RealtimeButton</span></span>
<span class="line"><span>ReadFormButton</span></span>
<span class="line"><span>ProgressBar</span></span>
<span class="line"><span>Image</span></span>
<span class="line"><span>Slider</span></span>
<span class="line"><span>Column</span></span></code></pre></div><h4 id="元素簡寫" tabindex="-1">元素簡寫 <a class="header-anchor" href="#元素簡寫" aria-label="Permalink to “元素簡寫”">​</a></h4><p>PySimpleGUI 還包含兩種元素簡寫方式。一種是元素類型名稱簡寫，例如 <code>T</code> 用作 <code>Text</code> 的簡寫；另一種是元素參數被配置了默認值，你可以無需指定所有參數，例如 <code>Submit</code> 按鈕默認的文本就是 “Submit”。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>T = Text</span></span>
<span class="line"><span>Txt = Text</span></span>
<span class="line"><span>In = InputText</span></span>
<span class="line"><span>Input = IntputText</span></span>
<span class="line"><span>Combo = InputCombo</span></span>
<span class="line"><span>DropDown = InputCombo</span></span>
<span class="line"><span>Drop = InputCombo</span></span></code></pre></div><p>（LCTT 譯註：第一種簡寫就是 Python 類的別名，第二種簡寫是在返回元素對象的 Python 函數定義時指定了參數的默認值）</p><h4 id="按鈕簡寫" tabindex="-1">按鈕簡寫 <a class="header-anchor" href="#按鈕簡寫" aria-label="Permalink to “按鈕簡寫”">​</a></h4><p>一些通用按鈕具有簡寫實現，包括：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>FolderBrowse</span></span>
<span class="line"><span>FileBrowse</span></span>
<span class="line"><span>FileSaveAs</span></span>
<span class="line"><span>Save</span></span>
<span class="line"><span>Submit</span></span>
<span class="line"><span>OK</span></span>
<span class="line"><span>Ok （LCTT 譯註：這裏 \`k\` 是小寫）</span></span>
<span class="line"><span>Cancel</span></span>
<span class="line"><span>Quit</span></span>
<span class="line"><span>Exit</span></span>
<span class="line"><span>Yes</span></span>
<span class="line"><span>No</span></span></code></pre></div><p>此外，還有通用按鈕功能對應的簡寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SimpleButton</span></span>
<span class="line"><span>ReadFormButton</span></span>
<span class="line"><span>RealtimeButton</span></span></code></pre></div><p>（LCTT 譯註：其實就是返回 <code>Button</code> 類實例的函數）</p><p>上面就是 PySimpleGUI 支持的全部元素。如果不在上述列表之中，就不會在你的窗口布局中生效。</p><p>（LCTT 譯註：上述都是 PySimpleGUI 的類名、類別名或返回實例的函數，自然只能使用列表內的。）</p><h4 id="gui-設計模式" tabindex="-1">GUI 設計模式 <a class="header-anchor" href="#gui-設計模式" aria-label="Permalink to “GUI 設計模式”">​</a></h4><p>對於 GUI 程序，創建並展示窗口的調用大同小異，差異在於元素的佈局。</p><p>設計模式代碼與上面的例子基本一致，只是移除了佈局：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import PySimpleGUI as sg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>form = sg.FlexForm(&#39;Simple data entry form&#39;)</span></span>
<span class="line"><span># Define your form here (it&#39;s a list of lists)</span></span>
<span class="line"><span>button, values = form.LayoutAndRead(layout)</span></span></code></pre></div><p>（LCTT 譯註：這段代碼無法運行，只是為了説明每個程序都會用到的設計模式。）</p><p>對於絕大多數 GUI，編碼流程如下：</p><ul><li>創建窗體對象</li><li>以“列表的列表”的形式定義 GUI</li><li>展示 GUI 並獲取元素的值</li></ul><p>上述流程與 PySimpleGUI 設計模式部分的代碼一一對應。</p><h4 id="gui-佈局" tabindex="-1">GUI 佈局 <a class="header-anchor" href="#gui-佈局" aria-label="Permalink to “GUI 佈局”">​</a></h4><p>要創建自定義 GUI，首先要將窗體分割成多個行，因為窗體是一行一行定義的。然後，在每一行中從左到右依次放置元素。</p><p>我們得到的就是一個“列表的列表”，類似如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>layout = [  [Text(&#39;Row 1&#39;)],</span></span>
<span class="line"><span>            [Text(&#39;Row 2&#39;), Checkbox(&#39;Checkbox 1&#39;, OK()), Checkbox(&#39;Checkbox 2&#39;), OK()] ]</span></span></code></pre></div><p>上述佈局對應的效果如下：</p><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui-custom-form.jpg" alt=""></p><h3 id="展示-gui" tabindex="-1">展示 GUI <a class="header-anchor" href="#展示-gui" aria-label="Permalink to “展示 GUI”">​</a></h3><p>當你完成佈局、拷貝完用於創建和展示窗體的代碼後，下一步就是展示窗體並收集用户數據。</p><p>下面這行代碼用於展示窗體並返回收集的數據：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>button, values = form.LayoutAndRead(layout)</span></span></code></pre></div><p>窗體返回的結果由兩部分組成：一部分是被點擊按鈕的名稱，另一部分是一個列表，包含所有用户輸入窗體的值。</p><p>在這個例子中，窗體顯示後用户直接點擊 “OK” 按鈕，返回的結果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>button == &#39;OK&#39;</span></span>
<span class="line"><span>values == [False, False]</span></span></code></pre></div><p>Checkbox 類型元素返回 <code>True</code> 或 <code>False</code> 類型的值。由於默認處於未選中狀態，兩個元素的值都是 <code>False</code>。</p><h3 id="顯示元素的值" tabindex="-1">顯示元素的值 <a class="header-anchor" href="#顯示元素的值" aria-label="Permalink to “顯示元素的值”">​</a></h3><p>一旦從 GUI 獲取返回值，檢查返回變量中的值是個不錯的想法。與其使用 <code>print</code> 語句進行打印，我們不妨堅持使用 GUI 並在一個窗口中輸出這些值。</p><p>（LCTT 譯註：考慮使用的是 Python 3 版本，<code>print</code> 應該是函數而不是語句。）</p><p>在 PySimpleGUI 中，有多種消息框可供選取。傳遞給消息框（函數）的數據會被顯示在消息框中；函數可以接受任意數目的參數，你可以輕鬆的將所有要查看的變量展示出來。</p><p>在 PySimpleGUI 中，最常用的消息框是 <code>MsgBox</code>。要展示上面例子中的數據，只需編寫一行代碼：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MsgBox(&#39;The GUI returned:&#39;, button, values)</span></span></code></pre></div><h3 id="整合" tabindex="-1">整合 <a class="header-anchor" href="#整合" aria-label="Permalink to “整合”">​</a></h3><p>好了，你已經瞭解了基礎知識，讓我們創建一個包含儘可能多 PySimpleGUI 元素的窗體吧！此外，為了更好的感觀效果，我們將採用綠色/棕褐色的配色方案。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import PySimpleGUI as sg</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sg.ChangeLookAndFeel(&#39;GreenTan&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>form = sg.FlexForm(&#39;Everything bagel&#39;, default_element_size=(40, 1))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>column1 = [[sg.Text(&#39;Column 1&#39;, background_color=&#39;#d3dfda&#39;, justification=&#39;center&#39;, size=(10,1))],</span></span>
<span class="line"><span>           [sg.Spin(values=(&#39;Spin Box 1&#39;, &#39;2&#39;, &#39;3&#39;), initial_value=&#39;Spin Box 1&#39;)],</span></span>
<span class="line"><span>           [sg.Spin(values=(&#39;Spin Box 1&#39;, &#39;2&#39;, &#39;3&#39;), initial_value=&#39;Spin Box 2&#39;)],</span></span>
<span class="line"><span>           [sg.Spin(values=(&#39;Spin Box 1&#39;, &#39;2&#39;, &#39;3&#39;), initial_value=&#39;Spin Box 3&#39;)]]</span></span>
<span class="line"><span>layout = [</span></span>
<span class="line"><span>    [sg.Text(&#39;All graphic widgets in one form!&#39;, size=(30, 1), font=(&quot;Helvetica&quot;, 25))],</span></span>
<span class="line"><span>    [sg.Text(&#39;Here is some text.... and a place to enter text&#39;)],</span></span>
<span class="line"><span>    [sg.InputText(&#39;This is my text&#39;)],</span></span>
<span class="line"><span>    [sg.Checkbox(&#39;My first checkbox!&#39;), sg.Checkbox(&#39;My second checkbox!&#39;, default=True)],</span></span>
<span class="line"><span>    [sg.Radio(&#39;My first Radio!     &#39;, &quot;RADIO1&quot;, default=True), sg.Radio(&#39;My second Radio!&#39;, &quot;RADIO1&quot;)],</span></span>
<span class="line"><span>    [sg.Multiline(default_text=&#39;This is the default Text should you decide not to type anything&#39;, size=(35, 3)),</span></span>
<span class="line"><span>     sg.Multiline(default_text=&#39;A second multi-line&#39;, size=(35, 3))],</span></span>
<span class="line"><span>    [sg.InputCombo((&#39;Combobox 1&#39;, &#39;Combobox 2&#39;), size=(20, 3)),</span></span>
<span class="line"><span>     sg.Slider(range=(1, 100), orientation=&#39;h&#39;, size=(34, 20), default_value=85)],</span></span>
<span class="line"><span>    [sg.Listbox(values=(&#39;Listbox 1&#39;, &#39;Listbox 2&#39;, &#39;Listbox 3&#39;), size=(30, 3)),</span></span>
<span class="line"><span>     sg.Slider(range=(1, 100), orientation=&#39;v&#39;, size=(5, 20), default_value=25),</span></span>
<span class="line"><span>     sg.Slider(range=(1, 100), orientation=&#39;v&#39;, size=(5, 20), default_value=75),</span></span>
<span class="line"><span>     sg.Slider(range=(1, 100), orientation=&#39;v&#39;, size=(5, 20), default_value=10),</span></span>
<span class="line"><span>     sg.Column(column1, background_color=&#39;#d3dfda&#39;)],</span></span>
<span class="line"><span>    [sg.Text(&#39;_&#39;  * 80)],</span></span>
<span class="line"><span>    [sg.Text(&#39;Choose A Folder&#39;, size=(35, 1))],</span></span>
<span class="line"><span>    [sg.Text(&#39;Your Folder&#39;, size=(15, 1), auto_size_text=False, justification=&#39;right&#39;),</span></span>
<span class="line"><span>     sg.InputText(&#39;Default Folder&#39;), sg.FolderBrowse()],</span></span>
<span class="line"><span>    [sg.Submit(), sg.Cancel()]</span></span>
<span class="line"><span>     ]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>button, values = form.LayoutAndRead(layout)</span></span>
<span class="line"><span>sg.MsgBox(button, values)</span></span></code></pre></div><p>看上面要寫不少代碼，但如果你試着直接使用 Tkinter 框架實現同樣的 GUI，你很快就會發現 PySimpleGUI 版本的代碼是多麼的簡潔。</p><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui-everything.jpg" alt=""></p><p>代碼的最後一行打開了一個消息框，效果如下：</p><p><img src="https://opensource.com/sites/default/files/uploads/pysimplegui-message-box.jpg" alt=""></p><p>消息框函數中的每一個參數的內容都會被打印到單獨的行中。本例的消息框中包含兩行，其中第二行非常長而且包含列表嵌套。</p><p>建議花一點時間將上述結果與 GUI 中的元素一一比對，這樣可以更好的理解這些結果是如何產生的。</p><h3 id="為你的程序或腳本添加-gui" tabindex="-1">為你的程序或腳本添加 GUI <a class="header-anchor" href="#為你的程序或腳本添加-gui" aria-label="Permalink to “為你的程序或腳本添加 GUI”">​</a></h3><p>如果你有一個命令列方式使用的腳本，添加 GUI 不一定意味着完全放棄該腳本。一種簡單的方案如下：如果腳本不需要命令列參數，那麼可以直接使用 GUI 調用該腳本；反之，就按原來的方式運行腳本。</p><p>僅需類似如下的邏輯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>if len(sys.argv) == 1:</span></span>
<span class="line"><span>        # collect arguments from GUI</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    # collect arguements from sys.argv</span></span></code></pre></div>`,68)),i("p",null,[s[6]||(s[6]=a("創建並運行 GUI 最便捷的方式就是從 ",-1)),e(n,{href:"https://pysimplegui.readthedocs.io/en/latest/cookbook/"},{default:p(()=>[...s[5]||(s[5]=[a("PySimpleGUI 經典實例",-1)])]),_:1}),s[7]||(s[7]=a("中拷貝一份代碼並修改。",-1))]),s[29]||(s[29]=l('<p>快來試試吧！給你一直疲於手動執行的腳本增加一些趣味。只需 5-10 分鐘即可玩轉示例腳本。你可能發現一個幾乎滿足你需求的經典實例；如果找不到，也很容易自己編寫一個。即使你真的玩不轉，也只是浪費了 5-10 分鐘而已。</p><h3 id="資源" tabindex="-1">資源 <a class="header-anchor" href="#資源" aria-label="Permalink to “資源”">​</a></h3><h4 id="安裝方式" tabindex="-1">安裝方式 <a class="header-anchor" href="#安裝方式" aria-label="Permalink to “安裝方式”">​</a></h4><p>支持 Tkinter 的系統就支持 PySimpleGUI，甚至包括<ruby>樹莓派<rt>Raspberry Pi</rt></ruby>，但你需要使用 Python 3。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pip install PySimpleGUI</span></span></code></pre></div><h4 id="文檔" tabindex="-1">文檔 <a class="header-anchor" href="#文檔" aria-label="Permalink to “文檔”">​</a></h4>',6)),i("ul",null,[i("li",null,[e(n,{href:"https://pysimplegui.readthedocs.io/en/latest/"},{default:p(()=>[...s[8]||(s[8]=[a("手冊",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://pysimplegui.readthedocs.io/en/latest/cookbook/"},{default:p(()=>[...s[9]||(s[9]=[a("經典實例",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://github.com/MikeTheWatchGuy/PySimpleGUI"},{default:p(()=>[...s[10]||(s[10]=[a("GitHub repository",-1)])]),_:1})])]),s[30]||(s[30]=i("hr",null,null,-1)),i("p",null,[s[12]||(s[12]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/18/8/pysimplegui"},{default:p(()=>[...s[11]||(s[11]=[a("https://opensource.com/article/18/8/pysimplegui",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/pysimplegui"},{default:p(()=>[...s[13]||(s[13]=[a("Mike Barnett",-1)])]),_:1}),s[18]||(s[18]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[14]||(s[14]=[a("lujun9972",-1)])]),_:1}),s[19]||(s[19]=a(" 譯者：",-1)),e(n,{href:"https://github.com/pinewall"},{default:p(()=>[...s[15]||(s[15]=[a("pinewall",-1)])]),_:1}),s[20]||(s[20]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[16]||(s[16]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[22]||(s[22]=[a("Linux中國",-1)])]),_:1}),s[25]||(s[25]=a(" 榮譽推出",-1))])])}const x=t(u,[["render",h]]);export{I as __pageData,x as default};
